<script setup lang="ts">import {ref,onMounted} from 'vue';import {useLab} from '../stores/laboratory';import {useAuth} from '../stores/auth';import {createRun} from '../api/runs';import {useTask} from '../hooks/useTask';import {usePolling} from '../hooks/usePolling';import PageTitle from '../components/common/PageTitle.vue';import ErrorNotice from '../components/common/ErrorNotice.vue';import DatasetSelect from '../components/DatasetSelect.vue';import RunTable from '../components/RunTable.vue';const lab=useLab(),auth=useAuth(),data=ref({name:'N02 · 晨间资格复核',dataset_id:0,lambda_ratio:1,allowance:2,range_low:0,range_high:100,bootstrap_count:500}),message=ref(''),{busy,error,perform}=useTask();onMounted(()=>perform(async()=>{await lab.load();data.value.dataset_id=lab.datasets[0]?.id||0;}));usePolling(async()=>{if(lab.runs.some(r=>['queued','running'].includes(r.status)))await lab.load();});function submit(){perform(async()=>{const r=await createRun(data.value);message.value=`研究 #${r.id} 已进入计算队列，完成后可读取比对簿。`;await lab.load();});}</script><template><PageTitle index="03" title="先写下假设，再计算差异" text="固定误差方差比、允许误差与观察范围；每次提交生成一份独立研究。"/><ErrorNotice :message="error" @retry="perform(lab.load)"/><div class="run-config-layout"><form class="research-form" v-if="auth.canEdit" @submit.prevent="submit"><h2>新建方法比对</h2><label>研究名称<input v-model="data.name" required minlength="2" maxlength="160"></label><DatasetSelect v-model="data.dataset_id" :datasets="lab.datasets"/><div class="form-grid two"><label>误差方差比 λ<input type="number" v-model.number="data.lambda_ratio" min=".01" max="100" step=".01" required></label><label>允许误差 ± / 百分点<input type="number" v-model.number="data.allowance" min=".01" max="50" step=".01" required></label></div><p class="input-note">λ = Var(候选Y测量误差) / Var(参考X测量误差)。λ=1表示两侧误差方差相等；不是观测值的方差比。</p><div class="form-grid two"><label>参考范围下限 %<input type="number" v-model.number="data.range_low" min="0" max="100" step=".1" required></label><label>参考范围上限 %<input type="number" v-model.number="data.range_high" min="0" max="100" step=".1" required></label></div><label>Bootstrap次数<select v-model="data.bootstrap_count"><option :value="200">200次</option><option :value="500">500次</option><option :value="1000">1000次</option></select></label><button class="primary" :disabled="busy||data.range_low>=data.range_high">{{busy?'正在提交…':'提交配对计算 →'}}</button><p v-if="message" class="success" role="status">{{message}}</p></form><section v-else class="research-form"><h2>观察员工作区</h2><p>可读取研究与已批准的交付数据；建立研究需要测量工程师权限。</p></section><aside class="method-notebook"><p class="eyebrow">ASSUMPTIONS / 方法边注</p><h2>两侧都有误差，<br>拟合也应同时考虑。</h2><div class="formula">Y = a + bX <span>Deming误差变量回归</span></div><ol><li><b>预先约定允许误差</b><p>业务门槛在计算前设定。相关系数没有资格判断权。</p></li><li><b>差值界限与其不确定性分开</b><p>LoA = 平均差 ± 1.96 SD；阴影为界限的95%bootstrap区间。</p></li><li><b>只讨论观察过的范围</b><p>整体界限假定独立样本、近似正态且差值波动稳定。异方差线索会阻止原值互换门槛。</p></li></ol><small>固定seed=73；bootstrap重采样完整配对。每次结果保留输入指纹。</small></aside></div><section class="run-directory"><div class="section-heading"><h2>研究目录</h2><span>运行中自动刷新</span></div><RunTable :runs="lab.runs"/></section></template>
